#include "defines.hpp"

// include benchmark-specific definitions
#include "atax.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A: m x n, row-major (i = row, j = column)
	DEFINE_PROTO_STRUCT(A_layout, j_vec ^ i_vec);
	// x: length n (dimension 'j')
	DEFINE_PROTO_STRUCT(x_layout, j_vec);
	// y: length n (dimension 'j')
	DEFINE_PROTO_STRUCT(y_layout, j_vec);
	// tmp: length m (dimension 'i')
	DEFINE_PROTO_STRUCT(tmp_layout, i_vec);
} tuning;

// Array initialization
void init_array(auto A, auto x) {
	using namespace noarr;

	// x: j dimension of length N
	const std::size_t n_len = x | get_length<'j'>();
	const num_t fn = static_cast<num_t>(n_len);
	// precompute reciprocal once to avoid a division in every iteration
	const num_t inv_fn = static_cast<num_t>(1) / fn;

	// x[j] = 1 + (j / fn)
	traverser(x).for_each([=](auto state) {
		const std::size_t j = get_index<'j'>(state);
		// mathematically equivalent to 1 + j / fn, but cheaper (mul instead of div)
		x[state] = static_cast<num_t>(1) + static_cast<num_t>(j) * inv_fn;
	});

	// A: dimensions i (M) and j (N)
	const std::size_t m_len   = A | get_length<'i'>();
	const std::size_t n_len_A = A | get_length<'j'>();

	// precompute scaling factor 1 / (5 * m) once
	const num_t inv_5m = static_cast<num_t>(1)
		/ (static_cast<num_t>(5) * static_cast<num_t>(m_len));

	// A[i][j] = ((i + j) % n) / (5 * m)
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		const std::size_t sum_ij = i + j;
		const num_t numerator = static_cast<num_t>(sum_ij % n_len_A);
		// numerator / (5*m) -> numerator * (1 / (5*m))
		A[state] = numerator * inv_5m;
	});
}

// Main computational kernel
// We keep the polybench region (#pragma scop) around the whole kernel body.
// The implementation uses Noarr traversers only (no raw for-loops over i/j).
[[gnu::flatten, gnu::noinline]]
void kernel_atax(auto A, auto x, auto y, auto tmp) {
	using namespace noarr;

	#pragma scop
	// y[j] = 0 for all j
	traverser(y).for_each([&](auto sy) {
		y[sy] = static_cast<num_t>(0);
	});

	// Fused form of the ATAX kernel:
	// for (i = 0; i < M; i++) {
	//   tmp[i] = 0;
	//   for (j = 0; j < N; j++)
	//     tmp[i] += A[i][j] * x[j];
	//   for (j = 0; j < N; j++)
	//     y[j] += A[i][j] * tmp[i];
	// }
	//
	// We traverse over rows i with for_dims<'i'> and then traverse the
	// remaining j dimension with for_each.  To reduce memory traffic on tmp,
	// we keep tmp[i] in a scalar accumulator and store it once per row.
	traverser(A, x, y, tmp).template for_dims<'i'>([&](auto row_trav) {
		// State with fixed i; can be used to index tmp[i]
		auto si = row_trav.state();

		// Accumulator for tmp[i], kept in a register to avoid repeated
		// loads/stores of tmp[i] inside the inner j loop.
		num_t tmp_i = static_cast<num_t>(0);

		// First pass over j:
		//   tmp_i = sum_j A[i][j] * x[j];
		row_trav.for_each([&](auto s) {
			// s contains indices 'i' and 'j'; x ignores 'i' since it has only 'j'
			tmp_i += A[s] * x[s];
		});

		// Materialize tmp[i] in memory to preserve original semantics
		tmp[si] = tmp_i;

		// Second pass over j:
		//   y[j] += A[i][j] * tmp[i];
		// We reuse row_trav to walk the same row again; A[i][j] is still likely
		// in cache, and we only read tmp_i from a register.
		row_trav.for_each([&](auto s) {
			y[s] += A[s] * tmp_i;
		});
	});
	#pragma endscop
}

} // namespace

