void init_array(auto A, auto x) {
	using namespace noarr;

	// x: j dimension of length N
	const std::size_t n_len = x | get_length<'j'>();
	const num_t inv_n = num_t(1) / num_t(n_len); // precompute reciprocal

	// x[j] = 1 + (j / n)  -->  x[j] = 1 + j * (1/n)
	traverser(x).for_each([&](auto state) {
		const std::size_t j = get_index<'j'>(state);
		x[state] = num_t(1) + num_t(j) * inv_n;
	});

	// A: dimensions i (M) and j (N)
	const std::size_t m_len = A | get_length<'i'>();
	const std::size_t n_len_A = A | get_length<'j'>();
	const num_t inv_5m = num_t(1) / (num_t(5) * num_t(m_len)); // 1 / (5 * m)

	// A[i][j] = ((i + j) % n) / (5 * m)
	// The expensive division is hoisted out of the loop as a multiplication.
	traverser(A).for_each([&](auto state) {
		const auto [i, j] = get_indices<'i', 'j'>(state);
		const num_t numerator = num_t((i + j) % n_len_A);
		A[state] = numerator * inv_5m;
	});
}

// -----------------------------------------------------------------------------
// Main computational kernel
// Computes y = A^T * (A * x)
// Original structure:
//   tmp[i] = sum_j A[i][j] * x[j]
//   y[j]   = sum_i A[i][j] * tmp[i]
// The original code interleaved these per-row; here we split into two phases:
//   1) compute tmp for all i
//   2) accumulate y using tmp
// This preserves the per-i and per-j accumulation order, so floating-point
// results remain bitwise identical to the original while enabling clearer
// optimization opportunities (register use, vectorization).
// -----------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_atax(auto A, auto x, auto y, auto tmp) {
	using namespace noarr;

	#pragma scop

	// ---------------------------------------------------------------------
	// y[j] = 0  for all j
	// ---------------------------------------------------------------------
	traverser(y).for_each([&](auto sy) {
		y[sy] = num_t(0);
	});

	// ---------------------------------------------------------------------
	// Phase 1: tmp[i] = sum_j A[i][j] * x[j]
	//
	// We iterate over rows (dimension 'i'), and for each row we accumulate
	// into a register 'sum' and store the result once into tmp[i].
	// Memory access:
	//   - A: streamed row-major (i fixed, j varying)
	//   - x: streamed over j
	//   - tmp: one write per row
	// ---------------------------------------------------------------------
	traverser(A, x, tmp).template for_dims<'i'>([&](auto inner) {
		// State with fixed i (contains index 'i')
		auto si = inner.state();

		num_t sum = num_t(0);

		// Iterate over remaining dimension 'j'
		inner.for_each([&](auto state) {
			// state has both 'i' and 'j'
			sum += A[state] * x[state];
		});

		tmp[si] = sum;
	});

	// ---------------------------------------------------------------------
	// Phase 2: y[j] += A[i][j] * tmp[i]
	//
	// Still traverse A row-major (i outer, j inner) for good data locality.
	// For each row i we load tmp[i] once into a register and reuse it for
	// the whole row. This removes repeated tmp[i] loads from the inner loop.
	//
	// Memory access:
	//   - A: streamed row-major (same as above)
	//   - tmp: one read per row
	//   - y: streamed over j
	// The accumulation order for each y[j] over i (0..M-1) is unchanged
	// compared to the original code; we only reorder independent work
	// (computing tmp for a given i vs updating y for some other i).
	// ---------------------------------------------------------------------
	traverser(A, tmp, y).template for_dims<'i'>([&](auto inner) {
		auto si = inner.state();        // fixed i
		const num_t t = tmp[si];       // reuse this across the whole row

		inner.for_each([&](auto state) {
			// state has both 'i' and 'j'
			y[state] += A[state] * t;
		});
	});

	#pragma endscop
}

