	DEFINE_PROTO_STRUCT(A_layout, j_vec ^ i_vec);
	// x: length n (dimension 'j')
	DEFINE_PROTO_STRUCT(x_layout, j_vec);
	// y: length n (dimension 'j')
	DEFINE_PROTO_STRUCT(y_layout, j_vec);
	// tmp: length m (dimension 'i')
	DEFINE_PROTO_STRUCT(tmp_layout, i_vec);
} tuning;

// Array initialization
void init_array(auto A, auto x) {
	using namespace noarr;

	// x: j dimension of length N
	auto n_len = x | get_length<'j'>();
	num_t fn = static_cast<num_t>(n_len);
	// Precompute reciprocal once to avoid a division per element
	const num_t inv_fn = static_cast<num_t>(1) / fn;

	// x[j] = 1 + (j / fn)
	traverser(x).for_each([=](auto state) {
		const auto j = get_index<'j'>(state);
		x[state] = static_cast<num_t>(1) + static_cast<num_t>(j) * inv_fn;
	});

	// A: dimensions i (M) and j (N)
	auto m_len = A | get_length<'i'>();
	auto n_len_A = A | get_length<'j'>();

	// Precompute 1 / (5 * m) once, instead of dividing in every iteration
	const num_t inv_5m = static_cast<num_t>(1) /
	                     static_cast<num_t>(5 * m_len);

	// A[i][j] = ((i + j) % n) / (5 * m)
	traverser(A).for_each([=](auto state) {
		const auto [i, j] = get_indices<'i', 'j'>(state);
		const num_t numerator =
		    static_cast<num_t>((i + j) % n_len_A);
		A[state] = numerator * inv_5m;
	});
}

// Main computational kernel
//
// Original mathematical operation (ATAX):
//   tmp[i] = sum_j A[i][j] * x[j]
//   y[j]   = sum_i A[i][j] * tmp[i]
//
// This implementation keeps the same computation but is structured
// into two clearly separated phases to enable better optimization
// and parallelization while preserving semantics.
[[gnu::flatten, gnu::noinline]]
void kernel_atax(auto A, auto x, auto y, auto tmp) {
	using namespace noarr;

	#pragma scop

	// -----------------------------------------------------------------
	// 0) Initialize y (and tmp) to 0
	// -----------------------------------------------------------------
	traverser(y).for_each([&](auto sy) {
		y[sy] = static_cast<num_t>(0);
	});

	// tmp is fully overwritten in phase 1, but zeroing it helps
	// if the calling environment ever inspects uncomputed entries.
	traverser(tmp).for_each([&](auto si) {
		tmp[si] = static_cast<num_t>(0);
	});

	// -----------------------------------------------------------------
	// 1) Compute tmp[i] = sum_j A[i][j] * x[j]
	//
	//   - Outer iteration over dimension 'i'
	//   - Inner for_each iterates dimension 'j'
	//   - We accumulate into a local scalar 'acc' to keep the reduction
	//     in registers and perform only a single store to tmp[i].
	//   - Parallelization: the iterations over 'i' are independent,
	//     so we parallelize the range-based loop over traverser(A,x,tmp).
	// -----------------------------------------------------------------
	auto trav_tmp = traverser(A, x, tmp);

	#ifdef _OPENMP
	#pragma omp parallel for schedule(static)
	#endif
	for (auto trav_i : trav_tmp) { // each trav_i has fixed 'i'
		const auto si = trav_i.state(); // state with this 'i'
		num_t acc = static_cast<num_t>(0);

		// iterate over 'j' for this fixed 'i'
		trav_i.for_each([&](auto s) {
			// s contains both 'i' and 'j'
			acc += A[s] * x[s];
		});

		tmp[si] = acc;
	}

	// -----------------------------------------------------------------
	// 2) Compute y[j] = sum_i A[i][j] * tmp[i]
	//
	//   - For each column j, we accumulate over all rows i.
	//   - We hoist 'j' to be the topmost dimension to drive the
	//     outer parallel loop by columns.
	//   - For each fixed 'j', an inner for_each iterates over 'i'.
	//   - tmp[state] ignores the 'j' index (tmp has only 'i'),
	//     which is explicitly allowed by Noarr: extra dimensions
	//     in the state are ignored by structures that do not use them.
	// -----------------------------------------------------------------
	auto trav_y = traverser(A, tmp, y).order(noarr::hoist<'j'>());

	#ifdef _OPENMP
	#pragma omp parallel for schedule(static)
	#endif
	for (auto trav_j : trav_y) { // each trav_j has fixed 'j'
		const auto sj = trav_j.state(); // state with this 'j'
		num_t acc = static_cast<num_t>(0);

		// iterate over 'i' (and any other remaining dims) for fixed j
		trav_j.for_each([&](auto s) {
			// s has both 'i' and 'j'
			acc += A[s] * tmp[s]; // tmp ignores 'j' component of s
		});

		y[sj] = acc;
	}

	#pragma endscop
}

} // namespace

