#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>
#include <noarr/structures/interop/traverser_iter.hpp> // enables range-based for over traversers

#ifdef _OPENMP
#include <omp.h>
#endif

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "atax.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A: m x n, row-major (i = row, j = column)
	DEFINE_PROTO_STRUCT(A_layout, j_vec ^ i_vec);
	// x: length n (dimension 'j')
	DEFINE_PROTO_STRUCT(x_layout, j_vec);
	// y: length n (dimension 'j')
	DEFINE_PROTO_STRUCT(y_layout, j_vec);
	// tmp: length m (dimension 'i')
	DEFINE_PROTO_STRUCT(tmp_layout, i_vec);
} tuning;

// Array initialization
void init_array(auto A, auto x) {
	using namespace noarr;

	// x: j dimension of length N
	auto n_len = x | get_length<'j'>();
	num_t fn = static_cast<num_t>(n_len);
	// Precompute reciprocal to avoid a division per element
	num_t inv_fn = static_cast<num_t>(1) / fn;

	// x[j] = 1 + (j / fn)
	traverser(x).for_each([&](auto state) {
		auto j = get_index<'j'>(state);
		x[state] = static_cast<num_t>(1) + static_cast<num_t>(j) * inv_fn;
	});

	// A: dimensions i (M) and j (N)
	auto m_len   = A | get_length<'i'>();
	auto n_len_A = A | get_length<'j'>();

	// Precompute 1 / (5 * m) once
	num_t inv_5m = static_cast<num_t>(1) /
	               (static_cast<num_t>(5) * static_cast<num_t>(m_len));

	// A[i][j] = ((i + j) % n) / (5 * m)
	traverser(A).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		num_t numerator = static_cast<num_t>((i + j) % n_len_A);
		A[state] = numerator * inv_5m;
	});
}

// Main computational kernel
//
// Original mathematical operation (ATAX):
//   tmp[i] = sum_j A[i][j] * x[j]
//   y[j]   = sum_i A[i][j] * tmp[i]
//
// The reference implementation fuses these two loops over j for each i:
//   for i:
//     tmp[i] = 0;
//     for j: tmp[i] += A[i][j] * x[j];
//     for j: y[j]  += A[i][j] * tmp[i];
//
// The implementation below keeps the same evaluation order within each i,
// but:
//   - uses a scalar accumulator tmp_i kept in a register to reduce
//     repeated memory traffic to tmp[i]
//   - optionally parallelizes over i using OpenMP with a privatized
//     copy of y per thread and a reduction afterwards
//   - uses only Noarr traversers for data traversal, as required
//
[[gnu::flatten, gnu::noinline]]
void kernel_atax(auto A, auto x, auto y, auto tmp) {
	using namespace noarr;

	// Problem sizes derived from the structures
	auto n_len = y | get_length<'j'>();
	auto m_len = tmp | get_length<'i'>();

	// Structure describing a 1D vector over 'j' (used for per-thread y copies)
	auto y_structure =
		noarr::scalar<num_t>() ^ tuning.y_layout ^ noarr::set_length<'j'>(n_len);

	#pragma scop
	// Initialize y to zero
	traverser(y).for_each([&](auto sy) {
		y[sy] = static_cast<num_t>(0);
	});

#if defined(_OPENMP)
	// ------------------------------
	// OpenMP parallel version
	// ------------------------------
	//
	// We parallelize over rows i. Each thread:
	//   - computes tmp[i] for its assigned rows
	//   - accumulates contributions to a private y_local[j]
	//
	// After the parallel region, we reduce all y_local into the global y.
	//
	// To keep extra memory under 50% of the original footprint, we compute
	// the maximum number of threads allowed by that constraint and cap
	// the OpenMP team size accordingly.

	if (m_len > 0 && n_len > 0) {
		// Original element count: |A| + |tmp| + |x| + |y|
		// = m*n + m + n + n = m*n + m + 2n
		const std::size_t base_elems =
			m_len * n_len + m_len + 2 * n_len;

		// Each thread holds a private y_local of length n_len,
		// so overhead (in elements) is num_threads * n_len.
		// We require: num_threads * n_len <= base_elems / 2
		const std::size_t max_threads_by_mem =
			std::max<std::size_t>(base_elems / (2 * n_len), 1);

		const std::size_t max_threads_omp =
			static_cast<std::size_t>(omp_get_max_threads());

		const std::size_t team_size =
			std::min(max_threads_by_mem, max_threads_omp);

		if (team_size > 1) {
			// Single contiguous buffer for all per-thread y_local vectors
			std::vector<num_t> y_private(team_size * n_len);

			// Parallel region with explicit team size
			#pragma omp parallel num_threads(static_cast<int>(team_size))
			{
				const int tid = omp_get_thread_num();
				num_t *local_data =
					y_private.data() + static_cast<std::size_t>(tid) * n_len;

				// Wrap the local buffer into a Noarr bag so all accesses
				// stay within the Noarr abstraction.
				auto y_local = noarr::make_bag(y_structure, static_cast<void*>(local_data));

				// Zero the local y for this thread
				traverser(y_local).for_each([&](auto sy) {
					y_local[sy] = static_cast<num_t>(0);
				});

				// Distribute rows (dimension 'i') among threads.
				// The traverser iterator iterates over the outermost
				// dimension of A,x,tmp, which is 'i' due to the row-major
				// layout (j_vec ^ i_vec).
				#pragma omp for schedule(static)
				for (auto inner : traverser(A, x, tmp)) {
					// State with fixed i (row index)
					auto si = inner.state();

					// Accumulator kept in a register to avoid repeated
					// loads/stores of tmp[i] in the inner loop
					num_t tmp_i = static_cast<num_t>(0);

					// First pass over j: tmp_i = sum_j A[i][j] * x[j]
					inner.for_each([&](auto state) {
						tmp_i += A[state] * x[state];
					});

					// Store final tmp[i]
					tmp[si] = tmp_i;

					// Second pass over j: y_local[j] += A[i][j] * tmp_i
					inner.for_each([&](auto state) {
						y_local[state] += A[state] * tmp_i;
					});
				}
			} // end parallel region

			// Reduction: y[j] = sum_t y_t_local[j]
			for (std::size_t t = 0; t < team_size; ++t) {
				num_t *local_data = y_private.data() + t * n_len;
				auto y_local = noarr::make_bag(y_structure, static_cast<void*>(local_data));

				traverser(y, y_local).for_each([&](auto sy) {
					y[sy] += y_local[sy];
				});
			}

			// Parallel path completed, we can return
			#pragma endscop
			return;
		}
	}
#endif // _OPENMP

	// ------------------------------
	// Sequential fallback
	// ------------------------------
	//
	// This path is used when OpenMP is not enabled, the problem is too
	// small to benefit from parallelism, or memory constraints disallow
	// multiple y copies. It is also a good baseline.
	//
	// The semantics are identical to the reference fused loops, but we
	// keep the per-row accumulator in a scalar tmp_i instead of updating
	// tmp[i] on every inner iteration.

	traverser(A, x, y, tmp).template for_dims<'i'>([&](auto inner) {
		// State with fixed i (row index)
		auto si = inner.state();

		// Accumulator kept in a register
		num_t tmp_i = static_cast<num_t>(0);

		// tmp[i] = sum_j A[i][j] * x[j]
		inner.for_each([&](auto state) {
			tmp_i += A[state] * x[state];
		});
		tmp[si] = tmp_i;

		// y[j] += A[i][j] * tmp[i]
		inner.for_each([&](auto state) {
			y[state] += A[state] * tmp_i;
		});
	});
	#pragma endscop
}

